func (q *Queries) TaskCounts(ctx context.Context, arg TaskCountsParams) ([]TaskCountsRow, error) {
	rows, err := q.db.Query(ctx, taskCounts, arg.StartDate, arg.EndDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TaskCountsRow{}
	for rows.Next() {
		var i TaskCountsRow
		if err := rows.Scan(
			&i.DepartmentID,
			&i.AssigneeEmployeeID,
			&i.DoneBy,
			&i.Status,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

